let sun=ctx.createRadialGradient(343,84,1,343,84,48);sun.addColorStop(0,'rgba(239,205,147,.42)');sun.addColorStop(1,'rgba(231,191,133,0)');ctx.fillStyle=sun;ctx.fillRect(280,30,130,110);
// Broken smoke banks.
for(let i=0;i<5;i++){let x=((i*137-gameTime*4)%(W+180)+W+180)%(W+180)-90,y=81+(i%3)*12;ctx.fillStyle=`rgba(53,58,53,${.09+i%2*.035})`;ctx.beginPath();ctx.ellipse(x,y,48+i%3*19,6+i%2*4,0,0,Math.PI*2);ctx.fill()}
