ctx.fillStyle='rgba(41,47,42,.35)';for(let i=0;i<10;i++){let x=i*58-15;ctx.fillRect(x,103+(i%3)*4,3,7);ctx.fillRect(x+8,108+(i%2)*4,2,5)}
// Ground shading and perspective mud flecks.
let ground=ctx.createLinearGradient(0,112,0,H);ground.addColorStop(0,'#706c59');ground.addColorStop(.38,'#4e4c3e');ground.addColorStop(1,'#262a22');ctx.fillStyle=ground;ctx.fillRect(0,112,W,H-112);
for(let i=0;i<180;i++){let x=(i*83+Math.sin(i*12.3)*43)%W,y=118+((i*37+Math.cos(i*3.1)*12)%(H-118)),sz=.4+((i*7)%7)/7;ctx.fillStyle=i%4===0?'rgba(181,153,105,.16)':'rgba(19,24,19,.2)';ctx.fillRect(x,y,sz*2,sz)}
// DDA wall pass. Every column is a textured ray with distance fog.
for(let x=0;x<W;x++){let cam=2*x/W-1,ra=player.a+Math.atan(cam*Math.tan(FOV/2)),rx=Math.cos(ra),ry=Math.sin(ra),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/rx),ddy=Math.abs(1/ry),sx=rx<0?-1:1,sy=ry<0?-1:1,sdx=(rx<0?player.x-mx:mx+1-player.x)*ddx,sdy=(ry<0?player.y-my:my+1-player.y)*ddy,side=0,steps=0;
while(steps++<45){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(mx<0||my<0||mx>=MW||my>=MH||map[my][mx])break}
let d=side?sdy-ddy:sdx-ddx;d=Math.max(.08,d*Math.cos(ra-player.a));zbuf[x]=d;if(mx<0||my<0||mx>=MW||my>=MH||!map[my][mx])continue;
let line=Math.min(H*1.65,H/d),top=H*.49-line*.5,bot=top+line;let wallX=side?player.x+d*rx:player.y+d*ry;wallX-=Math.floor(wallX);let type=map[my][mx],brick=Math.floor(wallX*8),v=(Math.sin(brick*17+mx*41+my*29)*.5+.5),shade=type===2?(side?1:.8):type===3?(side?1:.83):1;let r,g,b;if(type===2){r=78+v*22;g=67+v*19;b=52+v*15}else if(type===3){r=87+v*18;g=74+v*17;b=53+v*12}else{r=87+v*24;g=79+v*20;b=61+v*14}if(side){r*=.76;g*=.77;b*=.75}let fog=clamp(d/15,0,.76);r=r*shade*(1-fog)+105*fog;g=g*shade*(1-fog)+105*fog;b=b*shade*(1-fog)+93*fog;
ctx.fillStyle=`rgb(${r|0},${g|0},${b|0})`;ctx.fillRect(x,top,1,line);
// timber bands and rough cut texture
if(type!==1){let edge=(brick%2===0);if(edge&&line>9){ctx.fillStyle='rgba(24,25,20,.38)';ctx.fillRect(x,top+line*.27,1,Math.max(1,line*.035));ctx.fillRect(x,top+line*.72,1,Math.max(1,line*.025))}if(line>18&&v>.66){ctx.fillStyle='rgba(215,187,136,.12)';ctx.fillRect(x,top+line*(.12+v*.5),1,Math.max(1,line*.05))}}
// distant haze on lower edge
if(d>7){ctx.fillStyle=`rgba(167,159,137,${(d-7)*.018})`;ctx.fillRect(x,bot-2,1,2)}
}
// Wire, broken timber and shell craters as world-space sprites.
const project=(x,y)=>{let dx=x-player.x,dy=y-player.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-player.a;a=Math.atan2(Math.sin(a),Math.cos(a));return {d,z:d*Math.cos(a),sx:W/2+Math.tan(a)/Math.tan(FOV/2)*W/2}};
