// long shadow
ctx.fillStyle='rgba(17,19,16,.48)';ctx.beginPath();ctx.ellipse(4,1,33,7,0,0,Math.PI*2);ctx.fill();
// legs, boots
ctx.fillStyle='#37392f';ctx.fillRect(-13,-34,11,34);ctx.fillRect(3,-34,11,34);ctx.fillStyle='#252720';ctx.fillRect(-16,-4,15,5);ctx.fillRect(2,-4,15,5);
// khaki coat body
ctx.fillStyle=e.alert?'#62563d':'#665d43';ctx.beginPath();ctx.moveTo(-17,-36);ctx.lineTo(-14,-67);ctx.lineTo(-9,-75);ctx.lineTo(10,-75);ctx.lineTo(17,-64);ctx.lineTo(20,-36);ctx.lineTo(11,-31);ctx.lineTo(-12,-31);ctx.closePath();ctx.fill();
ctx.fillStyle='rgba(31,35,29,.45)';ctx.fillRect(-4,-70,3,30);ctx.fillRect(8,-67,3,24);ctx.fillStyle='#847653';ctx.fillRect(-12,-43,23,3);
// arms
ctx.strokeStyle='#5e543e';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-13,-65);ctx.lineTo(-24,-48);ctx.lineTo(-9,-50);ctx.moveTo(12,-64);ctx.lineTo(22,-50);ctx.lineTo(11,-48);ctx.stroke();
// rifle
ctx.strokeStyle='#30271f';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-13,-52);ctx.lineTo(29,-59);ctx.stroke();ctx.strokeStyle='#817052';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-53);ctx.lineTo(30,-58);ctx.stroke();
// head, helmet
ctx.fillStyle='#ad8865';ctx.beginPath();ctx.arc(0,-82,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#66654e';ctx.beginPath();ctx.ellipse(0,-88,12,5,0,Math.PI,Math.PI*2);ctx.lineTo(12,-86);ctx.quadraticCurveTo(0,-82,-12,-86);ctx.fill();ctx.fillStyle='#403f33';ctx.fillRect(-11,-85,22,2);
// subtle rim light
ctx.strokeStyle='rgba(210,186,133,.25)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-15,-65);ctx.lineTo(-10,-73);ctx.stroke();ctx.restore()}
// First-person rifle with subtle kick and brass glint.
let sway=Math.sin(moveBob)*2.1,kick=shotKick>0?Math.sin(shotKick/.22*Math.PI)*15:0;ctx.save();ctx.translate(0,kick);ctx.fillStyle='#252820';ctx.beginPath();ctx.moveTo(318,270);ctx.lineTo(346,220);ctx.lineTo(389,211);ctx.lineTo(427,270);ctx.fill();ctx.fillStyle='#77684c';ctx.beginPath();ctx.moveTo(350,270);ctx.lineTo(366,226);ctx.lineTo(382,221);ctx.lineTo(405,270);ctx.fill();ctx.fillStyle='#a18b61';ctx.fillRect(359,226,57,4);ctx.fillStyle='#292a24';ctx.fillRect(403,224,77,5);ctx.fillRect(407,231,54,3);ctx.fillStyle='#504b39';ctx.fillRect(388,216,23,12);ctx.fillStyle='#171b18';ctx.fillRect(374,219,8,5);ctx.fillStyle='#c2a76e';ctx.fillRect(432,223,2,4);ctx.fillStyle='#171a16';ctx.beginPath();ctx.moveTo(326,270);ctx.lineTo(345,235);ctx.lineTo(356,239);ctx.lineTo(342,270);ctx.fill();
// Sleeve / gloved hands
ctx.fillStyle='#77674d';ctx.beginPath();ctx.moveTo(325,270);ctx.lineTo(348,237);ctx.lineTo(361,242);ctx.lineTo(351,270);ctx.fill();ctx.fillStyle='#443d30';ctx.beginPath();ctx.ellipse(352,243,10,7,-.5,0,Math.PI*2);ctx.fill();
