 for(let i=0;i<54;i++){let x=(i*97+Math.floor(clock*3)*(i%5+1))%VW,y=Math.floor(horizon+27+((i*47+clock*(i%4+1)*7)%(VH-horizon-25)));ctx.fillStyle=i%3?'#77704d55':'#a08a5d44';ctx.fillRect(x,y,2+(i%5),1)}
 const dirX=Math.cos(player.a),dirY=Math.sin(player.a),planeX=-dirY*Math.tan(FOV/2),planeY=dirX*Math.tan(FOV/2);
 for(let x=0;x<VW;x++){
  let cameraX=2*x/VW-1,rayX=dirX+planeX*cameraX,rayY=dirY+planeY*cameraX,mapX=Math.floor(player.x),mapY=Math.floor(player.y);
