input.content:
import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = (await import('node:fs')).readFileSync(process.env.HOME + '/.local/share/omgithub-playwright/linux.json','utf8');
const launch = JSON.parse(config).browser.launchOptions;
process.env.DISPLAY ||= ':' + (await import('node:fs')).readFileSync(process.env.HOME + '/.local/share/omgithub-playwright/display','utf8').trim();
const browser = await chromium.launch(launch);
const page = await browser.newPage({viewport:{width:1280,height:720}, deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3002/',{waitUntil:'networkidle'});
await page.locator('#start').click();
await page.waitForTimeout(800);
await page.keyboard.down('KeyW'); await page.waitForTimeout(500); await page.keyboard.up('KeyW');
await page.mouse.click(640,360); await page.waitForTimeout(500);
mkdirSync('screenshots',{recursive:true});
await page.screenshot({path:'screenshots/iron-front-latest.jpg',type:'jpeg',quality:78});
console.log(JSON.stringify({title:await page.title(),hud:await page.locator('#hud').isVisible(),canvas:await page.locator('#scene').evaluate(c=>[c.width,c.height]),errors,ammo:await page.locator('#clip').textContent()},null,2));
await browser.close();

